    int[] datos = {38, 27, 43, 3, 9, 82, 10};
    mergeSort(datos, 0, datos.length - 1);
    System.out.println(Arrays.toString(datos));
  }
  static void mergeSort(int[] a, int inicio, int fin) {
    if (inicio >= fin) return;
    int medio = inicio + (fin - inicio) / 2;
    mergeSort(a, inicio, medio); mergeSort(a, medio + 1, fin);
    int[] temp = new int[fin - inicio + 1];
    int i = inicio, j = medio + 1, k = 0;
    while (i <= medio && j <= fin) temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i <= medio) temp[k++] = a[i++];
    while (j <= fin) temp[k++] = a[j++];
    System.arraycopy(temp, 0, a, inicio, temp.length);
  }
}

