    System.out.println(trie.startsWith("ro"));
  }
  static class Trie {
    static class Node { Map<Character,Node> next=new HashMap<>(); boolean word; }
    private final Node root=new Node();
    void add(String value) { Node n=root; for(char c:value.toCharArray()) n=n.next.computeIfAbsent(c,k->new Node()); n.word=true; }
    boolean walk(String value, boolean requireWord) { Node n=root; for(char c:value.toCharArray()){n=n.next.get(c);if(n==null)return false;} return !requireWord||n.word; }
    boolean contains(String value) { return walk(value,true); }
    boolean startsWith(String prefix) { return walk(prefix,false); }
  }
}

